def resolve(path, cwd, links):
    # Validate inputs
    if not cwd or cwd[0] != '/':
        return None
    if not path:
        return None

    # Start with the appropriate base path
    if path[0] == '/':
        current = '/'
        components = path[1:].split('/')
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    i = 0

    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                # Move to parent
                current = current.rsplit('/', 1)[0]
                if not current:
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            current = '/' + comp
        else:
            current = current + '/' + comp

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]

            # Parse remaining components after this one
            remaining = components[i+1:]

            # Parse target components
            if target[0] == '/':
                current = '/'
                target_components = target[1:].split('/')
            else:
                # Relative to the directory containing the link
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if not current:
                        current = '/'
                target_components = target.split('/')

            # Continue with target components followed by remaining
            components = target_components + remaining
            i = 0
        else:
            i += 1

    # Remove trailing slash except for root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

